create or replace function spiritual.compute_qibla ( p_lat numeric, p_lng numeric, out bearing numeric, out distance_km numeric ) language sql immutable as $$ with kaaba as (select 21.4225 as k_lat, 39.8262 as k_lng), trig as (select radians(p_lat) as phi1, radians(k_lat) as phi2, radians(k_lng - p_lng) as delta_lambda from kaaba), bearing_rad as (select atan2( sin(delta_lambda), cos(phi1) * tan(phi2) - sin(phi1) * cos(delta_lambda) ) as theta from trig), distance_rad as (select acos( sin(phi1) * sin(phi2) + cos(phi1) * cos(phi2) * cos(delta_lambda) ) as delta_sigma from trig) select degrees(theta) as bearing, (6371.0 * delta_sigma)::numeric(10,2) as distance_km from bearing_rad, distance_rad; $$;
